package app.space.notes.runtime;
import android.media.MediaPlayer;
import android.os.*;
import android.widget.*;
import android.view.Gravity;
import java.io.File;
import java.util.Locale;
/** Single-recording transport. Preparing, paused, ended and detached states release safely. */
final class VoicePlaybackCard extends LinearLayout {
 private final NotesDesign d;private final File audio;private final Runnable exclusive;private final java.util.function.Consumer<String> message;private final Button play;private final SeekBar progress;private final TextView time;private final Handler handler=new Handler(Looper.getMainLooper());
 private MediaPlayer player;private boolean prepared,disposed,seeking,boostRequested;private int duration;private android.media.audiofx.LoudnessEnhancer boost;private final CheckBox boostControl;
 private final Runnable tick=new Runnable(){public void run(){if(player==null || !prepared || disposed)return;try{if(!seeking)progress.setProgress(player.getCurrentPosition());showTime(player.getCurrentPosition());if(player.isPlaying())handler.postDelayed(this,250);}catch(IllegalStateException gone){playbackFailure();}}};
 VoicePlaybackCard(NotesDesign d,File audio,String state,String text,int duration,Runnable exclusive,java.util.function.Consumer<String> message,Runnable export,Runnable retry,Runnable open){super(d.context);this.d=d;this.audio=audio;this.duration=duration;this.exclusive=exclusive;this.message=message;setOrientation(VERTICAL);setPadding(d.dp(14),d.dp(14),d.dp(14),d.dp(12));android.graphics.drawable.GradientDrawable bg=d.shape(d.surface,18);bg.setStroke(d.dp(1),d.outline);setBackground(bg);setElevation(d.dp(1));LayoutParams margins=new LayoutParams(-1,-2);margins.setMargins(0,d.dp(6),0,d.dp(10));setLayoutParams(margins);
  addView(d.label(java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.MEDIUM,java.text.DateFormat.SHORT).format(new java.util.Date(audio.lastModified())),16,d.ink));String status=state.equals("REVIEW")?"Review transcript · uncertain words":state.equals("DONE")?"Transcript ready":state.toLowerCase(Locale.ROOT).contains("transcrib")?"Transcribing…":state.toLowerCase(Locale.ROOT).contains("fail")?"Transcript unavailable · retry":"Recording saved";TextView hint=d.label(status,13,d.muted);hint.setPadding(0,d.dp(6),0,d.dp(10));addView(hint);if(!text.isEmpty()){TextView words=d.label(text.length()>1000?text.substring(0,1000)+"…":text,17,d.ink);words.setTextIsSelectable(true);words.setMaxLines(4);words.setEllipsize(android.text.TextUtils.TruncateAt.END);addView(words);}
  LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);play=d.icon("Play","play",this::toggle);row.addView(play,new LayoutParams(d.dp(48),d.dp(48)));progress=new SeekBar(getContext());progress.setContentDescription("Recording playback position");progress.setEnabled(duration>0);progress.setMax(Math.max(1,duration));row.addView(progress,new LayoutParams(0,d.dp(48),1));row.addView(d.icon("Stop playback","stop",this::stop),new LayoutParams(d.dp(48),d.dp(48)));addView(row);time=d.label("",12,d.muted);time.setGravity(Gravity.END);addView(time);showTime(0);
  progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){seeking=true;}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user){if(player!=null && prepared)try{player.seekTo(value);}catch(IllegalStateException gone){playbackFailure();}showTime(value);}}public void onStopTrackingTouch(SeekBar bar){seeking=false;handler.removeCallbacks(tick);tick.run();}});
  boostControl=new CheckBox(getContext());boostControl.setText("Boost quiet playback (+6 dB)");boostControl.setTextColor(d.ink);boostControl.setMinHeight(d.dp(48));boostControl.setContentDescription("Optional six decibel playback boost. Does not remove noise or change the stored recording. Turn off if distorted.");boostControl.setOnCheckedChangeListener((button,on)->{boostRequested=on;if(on)applyBoost();else releaseBoost();});addView(boostControl);
  LinearLayout actions=new LinearLayout(getContext());actions.addView(d.icon("Export recording","export",export));actions.addView(d.icon("Retry transcript","retry",retry));actions.addView(d.icon("Open note","note",open));addView(actions);
 }
 private static String clock(int ms){return String.format(Locale.ROOT,"%d:%02d",ms/60000,(ms/1000)%60);}
 private void showTime(int position){time.setText(clock(position)+" / "+(duration>0?clock(duration):"—"));}
 private void playing(boolean value){String name=value?"Pause":"Play";play.setContentDescription(name);play.setTooltipText(name);NotesIcon icon=new NotesIcon(value?"pause":"play",d.ink);icon.setBounds(0,0,d.dp(24),d.dp(24));play.setCompoundDrawables(null,icon,null,null);}
 private void releaseBoost(){if(boost!=null){try{boost.release();}catch(RuntimeException ignored){/* Optional playback effect only. */}boost=null;}}
 private void applyBoost(){releaseBoost();if(!boostRequested || player==null || !prepared)return;try{boost=new android.media.audiofx.LoudnessEnhancer(player.getAudioSessionId());boost.setTargetGain(600);if(boost.setEnabled(true)!=android.media.audiofx.AudioEffect.SUCCESS)throw new IllegalStateException("Effect unavailable");}catch(RuntimeException | LinkageError unavailable){releaseBoost();boostRequested=false;boostControl.setChecked(false);message.accept("Playback boost is unavailable on this device. Normal playback and the original recording are unchanged.");}}
 private void playbackFailure(){release();message.accept("Could not play the recording. The original is retained; retry playback or export it.");}
 private void toggle(){if(disposed)return;Diagnostics.record("voice.transport","action=toggle");try{if(player!=null && prepared){if(player.isPlaying())pause();else{exclusive.run();player.start();playing(true);tick.run();}return;}if(player!=null)return;exclusive.run();player=new MediaPlayer();player.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setDataSource(audio.getPath());play.setEnabled(false);player.setOnPreparedListener(p->{if(disposed || p!=player){p.release();return;}try{exclusive.run();Diagnostics.record("voice.transport","state=prepared");prepared=true;int position=progress.getProgress();duration=p.getDuration();progress.setMax(Math.max(1,duration));progress.setEnabled(true);play.setEnabled(true);applyBoost();p.seekTo(Math.min(position,duration));p.start();playing(true);tick.run();}catch(RuntimeException failure){playbackFailure();}});player.setOnCompletionListener(p->{if(disposed || p!=player)return;try{handler.removeCallbacks(tick);p.seekTo(0);progress.setProgress(0);showTime(0);playing(false);}catch(IllegalStateException gone){playbackFailure();}});player.setOnErrorListener((p,what,extra)->{if(p!=player)return true;Diagnostics.record("voice.playback.error","what="+what+" extra="+extra);playbackFailure();return true;});player.prepareAsync();}catch(Exception | LinkageError failure){playbackFailure();}}
 void pause(){try{if(player!=null && !prepared){release();return;}if(player!=null && player.isPlaying())player.pause();handler.removeCallbacks(tick);playing(false);}catch(IllegalStateException gone){playbackFailure();}}
 private void stop(){Diagnostics.record("voice.transport","action=stop");try{if(player!=null && !prepared){release();return;}if(player!=null && prepared){player.pause();player.seekTo(0);}handler.removeCallbacks(tick);progress.setProgress(0);showTime(0);playing(false);}catch(IllegalStateException gone){playbackFailure();}}
 void release(){handler.removeCallbacks(tick);releaseBoost();if(player!=null){Diagnostics.record("voice.transport","state=released");MediaPlayer old=player;player=null;try{old.setOnPreparedListener(null);old.setOnCompletionListener(null);old.setOnErrorListener(null);old.release();}catch(RuntimeException ignored){/* Keep a failed device transport from taking down notes. */}}prepared=false;play.setEnabled(true);progress.setEnabled(duration>0);progress.setProgress(0);showTime(0);playing(false);}
 void dispose(){disposed=true;release();}
 @Override protected void onDetachedFromWindow(){dispose();super.onDetachedFromWindow();}
}
